INSERT INTO `exercicio` (`ID`, `Nome`, `Descricao`, `IdAutor`, `DataCadastro`, `Ativo`, `DescricaoHtml`) VALUES
	(1, 'Teste', NULL, 1, '2014-02-01 09:34:33', 0, '                            \r\n                                \r\n                                \r\n                                    Teste de descrição do exercício utilizando o editor HTML, porém não estou colocando nenhum estilo. Quero ver como será exibido o conteúdo deste exercício na listagem dos alunos.\r\n                                \r\n                            \r\n                        '),
	(2, 'Maçãs', NULL, 1, '2014-02-01 10:19:22', 1, 'Teste de exercício com descrição escrita em <b>html</b>'),
	(3, 'Array de Pontos 2D', NULL, 1, '2014-02-09 19:23:07', 1, 'Escreva para a classe <b>ArrayDePontos2D</b> acima um método <i>obtemPontoSuperior</i> que retorne o ponto cuja coordenada y é a maior dentre as encapsuladas no array; um método <i>obtemPontoInferior</i> que retorne o ponto cuja coordenada y é a menor dentre as encapsuladas no array; um método <i>obtemPontoMaisÀEsquerda</i> que retorne o ponto cuja coordenada y é a menor dentre as encapsuladas no array; e um método <i>obtemPontoMaisÀDireita</i> que retorne o ponto cuja coordenada y é a maior dentre as encapsuladas no array.'),
	(4, 'Promoção', NULL, 1, '2014-02-27 10:29:01', 1, '                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                Crie uma classe chamada Produto com os atributos Nome e Preco. Implemente os métodos Gets e Sets.'),
	(5, 'Exercicio 123', NULL, 1, '2014-03-08 14:16:00', 1, '                            \r\n                                \r\n                                    Informe a descrição do exercício\r\n                                \r\n                                \r\n                            \r\n                        '),
	(6, 'Novo Exercício AAA', NULL, 1, '2014-03-16 22:16:54', 1, '                            \r\n                                \r\n                                \r\n                                                                                                                                    Preencha aqui o conteúdo do novo exercício!\r\n                                \r\n                            \r\n                        '),
	(7, 'Aluno', NULL, 8, '2015-01-08 22:31:11', 1, '                            \r\n                                \r\n                                \r\n                                                                                                                                    Crie uma classe aluno com os atributos Nome, Número da Matrícula e seus getters e setters\r\n                                \r\n                            \r\n                        ');
INSERT INTO `exercicioclassevalidacao` (`ID`, `IdExercicio`, `Fonte`, `Saida`, `MensagemCompilacao`, `Mensagem`, `DataCadastro`, `Ativo`, `Ordem`) VALUES
	(2, 6, 'Pessoa x = new Pessoa();', '', 'O nome da sua classe não segue o formato esperado, ou não foi possível localizar a sua classe.', '', '2014-05-18 19:16:57', 1, 1),
	(3, 6, 'Pessoa x = new Pessoa();\r\nx.setNome(123);', '', 'O método \'set\' não segue a assinatura especificada no exercício: ou o nome do método ou os tipos dos parâmetros não segue o formato esperado.', '', '2014-05-18 19:16:57', 1, 2),
	(4, 6, 'Pessoa x = new Pessoa();\r\nx.setNome(123);\r\nSystem.out.println(x.getNome());', '123', 'O método \'get\' não segue a assinatura especificada no exercício: ou o nome do método ou os tipos dos parâmetros não segue o formato esperado.', 'O valor retornado pelo método \'get\' não é o valor esperado!', '2014-05-18 19:16:57', 1, 3),
	(5, 6, 'Pessoa x = new Pessoa();\r\nx.setTelefone(123);', '', 'O método \'set\' não segue a assinatura especificada no exercício: ou o nome do método ou os tipos dos parâmetros não segue o formato esperado.', '', '2014-05-18 19:16:57', 1, 4),
	(6, 6, 'Pessoa x = new Pessoa();\r\nx.setTelefone(123);\r\nSystem.out.println(x.getTelefone());', '123', 'O método \'get\' não segue a assinatura especificada no exercício: ou o nome do método ou os tipos dos parâmetros não segue o formato esperado.', 'O valor retornado pelo método \'get\' não é o valor esperado!', '2014-05-18 19:16:57', 1, 5),
	(7, 6, 'Pessoa x = new Pessoa();\r\nx.setEmail(123);', '', 'O método \'set\' não segue a assinatura especificada no exercício: ou o nome do método ou os tipos dos parâmetros não segue o formato esperado.', '', '2014-05-18 19:16:57', 1, 6),
	(8, 6, 'Pessoa x = new Pessoa();\r\nx.setEmail(123);\r\nSystem.out.println(x.getEmail());', '123', 'O método \'get\' não segue a assinatura especificada no exercício: ou o nome do método ou os tipos dos parâmetros não segue o formato esperado.', 'O valor retornado pelo método \'get\' não é o valor esperado!', '2014-05-18 19:16:57', 1, 7),
	(9, 4, 'Produto x = new Produto();', '', 'O nome da sua classe não segue o formato esperado, ou não foi possível localizar a sua classe.', '', '2014-03-26 01:03:36', 1, NULL),
	(10, 4, 'Produto x = new Produto();\r\nx.setNome("Produto Teste");', '', 'O método \'set\' não segue a assinatura especificada no exercício: ou o nome do método ou os tipos dos parâmetros não segue o formato esperado.', '', '2014-03-26 01:03:36', 1, NULL),
	(11, 4, 'Produto x = new Produto();\r\nx.setNome("Produto Teste");\r\nSystem.out.println(x.getNome());', 'Produto Teste', 'O método \'get\' não segue a assinatura especificada no exercício: ou o nome do método ou os tipos dos parâmetros não segue o formato esperado.', 'O valor retornado pelo método \'get\' não é o valor esperado!', '2014-03-26 01:03:36', 1, NULL),
	(12, 4, 'Produto x = new Produto();\r\nx.setPreco(199);', '', 'O método \'set\' não segue a assinatura especificada no exercício: ou o nome do método ou os tipos dos parâmetros não segue o formato esperado.', '', '2014-03-26 01:03:36', 1, NULL),
	(13, 4, 'Produto x = new Produto();\r\nx.setPreco(199);\r\nSystem.out.println(x.getPreco());', '199', 'O método \'get\' não segue a assinatura especificada no exercício: ou o nome do método ou os tipos dos parâmetros não segue o formato esperado.', 'O valor retornado pelo método \'get\' não é o valor esperado!', '2014-03-26 01:03:36', 1, NULL);
