	(3, 3, 'Solution.java', '/* package qualquer; // Não coloque nome no package */\r\n\r\nimport java.util.*;\r\nimport java.lang.*;\r\nimport java.io.*;\r\n\r\n/* O nome da classe deve ser "Solution" */\r\nclass Solution\r\n{\r\n    public static void main (String[] args) throws java.lang.Exception\r\n    {\r\n        System.out.println(123);\r\n    }\r\n}'),
