	(29, 18, 'Produto.java', '/* package qualquer; // Não coloque nome no package */\r\n\r\nimport java.util.*;\r\nimport java.lang.*;\r\nimport java.io.*;\r\n\r\nclass Produto\r\n{\r\n   private String nome;\r\n   private int preco;\r\n   \r\n   public void setNome(String nome)\r\n   {\r\n       this.nome = nome;\r\n   }\r\n   public String getNome()\r\n   {\r\n       return this.nome;\r\n   }\r\n   public void setPreco(int preco)\r\n   {\r\n       this.preco = preco;\r\n   }\r\n   public int getPreco()\r\n   {\r\n       return this.preco;\r\n   }\r\n}'),
