	(31, 19, 'Produto.java', '/* package qualquer; // Não coloque nome no package */\r\n\r\nimport java.util.*;\r\nimport java.lang.*;\r\nimport java.io.*;\r\n\r\nclass Produto\r\n{\r\n   private String nome;\r\n   private int preco;\r\n   \r\n   public void setNome(String nome)\r\n   {\r\n       this.nome = nome;\r\n   }\r\n   public String getNome()\r\n   {\r\n       return this.nome;\r\n   }\r\n   public void setPreco(int preco)\r\n   {\r\n       this.preco = preco;\r\n   }\r\n   public int getPreco()\r\n   {\r\n       return this.preco;\r\n   }\r\n}'),
	(32, 20, 'CodejudgeCompiler.java', '/*\r\n * Codejudge\r\n * Copyright 2012, Sankha Narayan Guria (sankha93@gmail.com)\r\n * Licensed under MIT License.\r\n *\r\n * Codejudge Compiler Server\r\n */\r\n \r\n\r\nimport java.io.BufferedWriter;\r\nimport java.io.FileNotFoundException;\r\nimport java.io.FileOutputStream;\r\nimport java.io.IOException;\r\nimport java.io.OutputStreamWriter;\r\nimport java.net.ServerSocket;\r\nimport java.net.Socket;\r\n\r\npublic class CodejudgeCompiler {\r\n	\r\n    public static void main(String args[]) {\r\n        \r\n        createFile("teste.txt", "sssss");\r\n        \r\n//        int n=0;\r\n//        try {\r\n//            ServerSocket server = new ServerSocket(3029); // create a new socket to listen on\r\n//            System.out.println("Codejudge compilation server running ...");\r\n//            while(true) {\r\n//                n++;\r\n//                // accept any incoming connection and process it on a new thread\r\n//                Socket s = server.accept();\r\n//                RequestThread request = new RequestThread(s, n);\r\n//                request.start();\r\n//                \r\n//            }\r\n//        } catch (IOException e) {\r\n//            e.printStackTrace();\r\n//        }\r\n    }\r\n    \r\n    private static void createFile(String file, String contents)\r\n    {\r\n        try {\r\n            BufferedWriter out = new BufferedWriter(new OutputStreamWriter(new FileOutputStream(file, false)));\r\n            out.write(contents);\r\n            out.close();\r\n        } catch (FileNotFoundException e) {\r\n            e.printStackTrace();\r\n        } catch (IOException e) {\r\n            e.printStackTrace();\r\n        }\r\n    }\r\n}\r\n'),
	(33, 21, 'CodejudgeCompiler.java', '/*\r\n * Codejudge\r\n * Copyright 2012, Sankha Narayan Guria (sankha93@gmail.com)\r\n * Licensed under MIT License.\r\n *\r\n * Codejudge Compiler Server\r\n */\r\n \r\n\r\nimport java.io.BufferedWriter;\r\nimport java.io.FileNotFoundException;\r\nimport java.io.FileOutputStream;\r\nimport java.io.IOException;\r\nimport java.io.OutputStreamWriter;\r\nimport java.net.ServerSocket;\r\nimport java.net.Socket;\r\n\r\npublic class CodejudgeCompiler {\r\n	\r\n    public static void main(String args[]) {\r\n        \r\n        createFile("teste.txt", "sssss");\r\n        \r\n//        int n=0;\r\n//        try {\r\n//            ServerSocket server = new ServerSocket(3029); // create a new socket to listen on\r\n//            System.out.println("Codejudge compilation server running ...");\r\n//            while(true) {\r\n//                n++;\r\n//                // accept any incoming connection and process it on a new thread\r\n//                Socket s = server.accept();\r\n//                RequestThread request = new RequestThread(s, n);\r\n//                request.start();\r\n//                \r\n//            }\r\n//        } catch (IOException e) {\r\n//            e.printStackTrace();\r\n//        }\r\n    }\r\n    \r\n    private static void createFile(String file, String contents)\r\n    {\r\n        try {\r\n            BufferedWriter out = new BufferedWriter(new OutputStreamWriter(new FileOutputStream(file, false)));\r\n            out.write(contents);\r\n            out.close();\r\n        } catch (FileNotFoundException e) {\r\n            e.printStackTrace();\r\n        } catch (IOException e) {\r\n            e.printStackTrace();\r\n        }\r\n    }\r\n}\r\n'),
	(34, 21, 'Reta.java', '\r\n/**\r\n * Escreva a descrição da classe Reta aqui.\r\n * \r\n * @author (seu nome) \r\n * @version (número de versão ou data)\r\n */\r\npublic class Reta\r\n{\r\n    private Ponto p;\r\n    private Ponto q;\r\n    \r\n    private double Largura;\r\n\r\n    /**\r\n     * COnstrutor para objetos da classe Ponto\r\n     */\r\n    public Reta(){}\r\n    public Reta (Ponto p, Ponto q){\r\n        this.p=p;\r\n        this.q=q;\r\n    }\r\n    \r\n    public Ponto getP(){\r\n        return this.p;\r\n    }\r\n    \r\n    public void setP(Ponto p){\r\n        this.p = p;\r\n    }\r\n    \r\n    public Ponto getQ(){\r\n        return this.q;\r\n    }\r\n    \r\n    public void setQ(Ponto q){\r\n        this.p = q;\r\n    }\r\n        \r\n    public double getDistancia (){\r\n        double a = Math.pow(p.getX()-q.getX(), 2)+ Math.pow(p.getY()-q.getY(), 2) ; \r\n        double distancia= Math.sqrt(a);\r\n        \r\n     return distancia ;   \r\n        \r\n    }\r\n    \r\n}\r\n'),
	(35, 22, 'CodejudgeCompiler.java', '/*\r\n * Codejudge\r\n * Copyright 2012, Sankha Narayan Guria (sankha93@gmail.com)\r\n * Licensed under MIT License.\r\n *\r\n * Codejudge Compiler Server\r\n */\r\n \r\n\r\nimport java.io.BufferedWriter;\r\nimport java.io.FileNotFoundException;\r\nimport java.io.FileOutputStream;\r\nimport java.io.IOException;\r\nimport java.io.OutputStreamWriter;\r\nimport java.net.ServerSocket;\r\nimport java.net.Socket;\r\n\r\npublic class CodejudgeCompiler {\r\n	\r\n    public static void main(String args[]) {\r\n        \r\n        createFile("teste.txt", "sssss");\r\n        \r\n//        int n=0;\r\n//        try {\r\n//            ServerSocket server = new ServerSocket(3029); // create a new socket to listen on\r\n//            System.out.println("Codejudge compilation server running ...");\r\n//            while(true) {\r\n//                n++;\r\n//                // accept any incoming connection and process it on a new thread\r\n//                Socket s = server.accept();\r\n//                RequestThread request = new RequestThread(s, n);\r\n//                request.start();\r\n//                \r\n//            }\r\n//        } catch (IOException e) {\r\n//            e.printStackTrace();\r\n//        }\r\n    }\r\n    \r\n    private static void createFile(String file, String contents)\r\n    {\r\n        try {\r\n            BufferedWriter out = new BufferedWriter(new OutputStreamWriter(new FileOutputStream(file, false)));\r\n            out.write(contents);\r\n            out.close();\r\n        } catch (FileNotFoundException e) {\r\n            e.printStackTrace();\r\n        } catch (IOException e) {\r\n            e.printStackTrace();\r\n        }\r\n    }\r\n}\r\n'),
	(36, 22, 'Reta.java', '\r\n/**\r\n * Escreva a descrição da classe Reta aqui.\r\n * \r\n * @author (seu nome) \r\n * @version (número de versão ou data)\r\n */\r\npublic class Reta\r\n{\r\n    private Ponto p;\r\n    private Ponto q;\r\n    \r\n    private double Largura;\r\n\r\n    /**\r\n     * COnstrutor para objetos da classe Ponto\r\n     */\r\n    public Reta(){}\r\n    public Reta (Ponto p, Ponto q){\r\n        this.p=p;\r\n        this.q=q;\r\n    }\r\n    \r\n    public Ponto getP(){\r\n        return this.p;\r\n    }\r\n    \r\n    public void setP(Ponto p){\r\n        this.p = p;\r\n    }\r\n    \r\n    public Ponto getQ(){\r\n        return this.q;\r\n    }\r\n    \r\n    public void setQ(Ponto q){\r\n        this.p = q;\r\n    }\r\n        \r\n    public double getDistancia (){\r\n        double a = Math.pow(p.getX()-q.getX(), 2)+ Math.pow(p.getY()-q.getY(), 2) ; \r\n        double distancia= Math.sqrt(a);\r\n        \r\n     return distancia ;   \r\n        \r\n    }\r\n    \r\n}\r\n'),
	(37, 22, 'Texto.java', '/**\r\n * Write a description of class Texto here.\r\n * \r\n * @author (your name) \r\n * @version (a version number or a date)\r\n */\r\npublic class Texto\r\n{\r\n   private String texto;\r\n   \r\n   public Texto(String tx){\r\n       texto =tx;\r\n    }\r\n    public String toString(){\r\n      String res =new String("" + texto);\r\n        return res;\r\n    }\r\n    \r\n    public void mudaTexto(String texto){\r\n        this.texto= texto;\r\n    }\r\n    \r\n     public String compactaTexto(){\r\n          return texto.replaceAll(" ", "");\r\n\r\n    }\r\n    \r\n\r\n           \r\n\r\n  public String inverteTexto (){\r\n       String ret = "";\r\n\r\n       for ( int  i = texto.length()-1; i >=0; i--){\r\n           char c = texto.charAt(i);\r\n           ret += c;\r\n        }\r\n        return ret;\r\n    }\r\n\r\n public int contaCaracteres(char caracter){\r\n    int cont = 0;\r\n    int i = 0;\r\n    String s = texto.toUpperCase();\r\n\r\n    while (i < s.length()){\r\n        \r\n        if (s.charAt(i) == Character.toUpperCase(caracter))\r\n           cont++;\r\n        \r\n        i++;\r\n    }\r\n     return cont;\r\n    }\r\n    \r\n    public String maiorPalavra(){\r\n        String[] result = texto.split(" ");\r\n        String maior = "";\r\n        \r\n        for(String s : result){\r\n            // for em cada palavra\r\n            \r\n            if (s.length() > maior.length())\r\n                maior = s;\r\n        }\r\n        \r\n        if (maior.length() == 0) maior = texto;\r\n        \r\n        return maior;\r\n    }\r\n    \r\n }\r\n'),
	(38, 22, 'TTT.java', '\r\n/**\r\n * Write a description of class Texto here.\r\n * \r\n * @author (your name) \r\n * @version (a version number or a date)\r\n */\r\npublic class Texto\r\n{\r\n    private String texto;\r\n    \r\n    public Texto(String texto){this.texto = texto;}\r\n    \r\n    public String toString(){\r\n        return ""+this.texto+"";\r\n    }\r\n    \r\n    public void mudaTexto(String texto){\r\n        this.texto = texto;\r\n    }\r\n    \r\n    public String inverteTexto(){\r\n        int comprimento = texto.length();\r\n        String invertido = "";\r\n        for (int i = comprimento -1; i >= 0; i--){\r\n            invertido += texto.charAt(i);\r\n        }    \r\n        return invertido;   \r\n    }\r\n    \r\n    public int contaCaracteres(char caracter){\r\n        int i = 0;\r\n        int contCaracter = 0;\r\n        while(i < texto.length() -1){\r\n            texto = texto.toLowerCase();\r\n            for (int j = 1; j >= 0; j--){\r\n            if(texto.charAt(i) == caracter){  \r\n                contCaracter++;}\r\n            i++;}\r\n        }\r\n        return contCaracter;\r\n    }\r\n    \r\n    public String compactaTexto(){\r\n        int comprimento = texto.length();\r\n        String textofinal = "";\r\n        for (int i = 0; i <= comprimento -1; i++){\r\n            if(texto.charAt(i) != \' \')\r\n            textofinal += texto.charAt(i);        \r\n        }    \r\n        return textofinal;   \r\n    }\r\n    \r\n    public String maiorPalavra(){\r\n        String sentenca = texto + " ";\r\n        int comprimento = sentenca.length();\r\n        String maior = "";\r\n        String palavra = "";\r\n        int p;\r\n        char c;\r\n        for (int i = 0; i <= comprimento -1; i++){\r\n         c = sentenca.charAt(i);\r\n              if(c != \' \'){ \r\n                  palavra += c;\r\n              }\r\n              else {p = palavra.length();\r\n                  if (p > maior.length()){\r\n                      maior = palavra;\r\n                  }\r\n                  palavra = "";\r\n              }\r\n        }\r\n        return maior;\r\n    }     \r\n}   \r\n\r\n'),
	(39, 23, 'CodejudgeCompiler.java', '/*\r\n * Codejudge\r\n * Copyright 2012, Sankha Narayan Guria (sankha93@gmail.com)\r\n * Licensed under MIT License.\r\n *\r\n * Codejudge Compiler Server\r\n */\r\n \r\n\r\nimport java.io.BufferedWriter;\r\nimport java.io.FileNotFoundException;\r\nimport java.io.FileOutputStream;\r\nimport java.io.IOException;\r\nimport java.io.OutputStreamWriter;\r\nimport java.net.ServerSocket;\r\nimport java.net.Socket;\r\n\r\npublic class CodejudgeCompiler {\r\n	\r\n    public static void main(String args[]) {\r\n        \r\n        createFile("teste.txt", "sssss");\r\n        \r\n//        int n=0;\r\n//        try {\r\n//            ServerSocket server = new ServerSocket(3029); // create a new socket to listen on\r\n//            System.out.println("Codejudge compilation server running ...");\r\n//            while(true) {\r\n//                n++;\r\n//                // accept any incoming connection and process it on a new thread\r\n//                Socket s = server.accept();\r\n//                RequestThread request = new RequestThread(s, n);\r\n//                request.start();\r\n//                \r\n//            }\r\n//        } catch (IOException e) {\r\n//            e.printStackTrace();\r\n//        }\r\n    }\r\n    \r\n    private static void createFile(String file, String contents)\r\n    {\r\n        try {\r\n            BufferedWriter out = new BufferedWriter(new OutputStreamWriter(new FileOutputStream(file, false)));\r\n            out.write(contents);\r\n            out.close();\r\n        } catch (FileNotFoundException e) {\r\n            e.printStackTrace();\r\n        } catch (IOException e) {\r\n            e.printStackTrace();\r\n        }\r\n    }\r\n}\r\n'),
	(40, 23, 'Texto.java', '/* package qualquer; // Não coloque nome no package */\n \n import java.util.*;\n import java.lang.*;\n import java.io.*;\n \n class Endereco.java\n {\n    // Coloque aqui o seu códigooooooooooo\n	< a href="#" >Teste< /a >\n }');
